import { MongoClient } from 'mongodb';

const client = new MongoClient(process.env.MONGODB_URI);
const accounts = client.db('shop').collection('accounts');

async function transfer(from, to, amount) {
  const session = client.startSession();
  try {
    return await session.withTransaction(async () => {
      const source = await accounts.findOne({ _id: from }, { session });
      if (!source || source.balance < amount) {
        throw new Error(`insufficient funds in ${from}`);
      }
      await accounts.updateOne({ _id: from }, { $inc: { balance: -amount } }, { session });
      await accounts.updateOne({ _id: to }, { $inc: { balance: amount } }, { session });
      return 'committed';
    });
  } finally {
    await session.endSession();
  }
}

